  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "representation" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, representation) REFERENCES principal_representation (tenant, id)
);

CREATE TABLE candidate_evaluation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "candidate" TEXT NOT NULL,
  "run" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, candidate) REFERENCES release_candidate (tenant, id),
  FOREIGN KEY (tenant, run) REFERENCES evaluation_run (tenant, id)
);

CREATE TABLE candidate_qualification (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "candidate" TEXT NOT NULL,
  "policy" TEXT NOT NULL,
  "evaluation" TEXT,
  "decision" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, candidate) REFERENCES release_candidate (tenant, id),
  FOREIGN KEY (tenant, evaluation) REFERENCES evaluation_finish (tenant, id),
  FOREIGN KEY (tenant, decision) REFERENCES decision_outcome (tenant, id)
);

CREATE TABLE promotion (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "series" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "previous" TEXT,
  "kind" TEXT NOT NULL,
  "release" TEXT NOT NULL,
  "channel" TEXT,
  "command_key" TEXT,
  "reason" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, series) REFERENCES publication_series (tenant, id),
  FOREIGN KEY (tenant, previous) REFERENCES promotion (tenant, id),
  FOREIGN KEY (tenant, release) REFERENCES release (tenant, id),
  FOREIGN KEY (tenant, channel) REFERENCES publication_channel (tenant, id)
);

CREATE TABLE publication_channel (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "series" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "audience" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, series) REFERENCES publication_series (tenant, id),
  FOREIGN KEY (tenant, audience) REFERENCES participation_set (tenant, id)
);

CREATE TABLE publication_series (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE release (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "series" TEXT NOT NULL,
  "candidate" TEXT NOT NULL,
  "qualification" TEXT NOT NULL,
  "specification" TEXT NOT NULL,
  "artifact" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, series) REFERENCES publication_series (tenant, id),
  FOREIGN KEY (tenant, candidate) REFERENCES release_candidate (tenant, id),
  FOREIGN KEY (tenant, qualification) REFERENCES candidate_qualification (tenant, id),
  FOREIGN KEY (tenant, specification) REFERENCES specification_pin (tenant, id),
  FOREIGN KEY (tenant, artifact) REFERENCES artifact_revision (tenant, id)
);

CREATE TABLE release_audience_link (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "promotion" TEXT NOT NULL,
  "release" TEXT NOT NULL,
  "channel" TEXT NOT NULL,
  "audience" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, promotion) REFERENCES promotion (tenant, id),
  FOREIGN KEY (tenant, release) REFERENCES release (tenant, id),
  FOREIGN KEY (tenant, channel) REFERENCES publication_channel (tenant, id),
  FOREIGN KEY (tenant, audience) REFERENCES participation_set (tenant, id)
);

CREATE TABLE release_candidate (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "series" TEXT NOT NULL,
  "version" TEXT NOT NULL,
  "specification" TEXT NOT NULL,
  "artifact" TEXT NOT NULL,
  "policy" TEXT NOT NULL,
  "evaluation_definition" TEXT,
  "decision_case" TEXT,
  "approved_option" TEXT,
  "support" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, series) REFERENCES publication_series (tenant, id),
  FOREIGN KEY (tenant, specification) REFERENCES specification_pin (tenant, id),
  FOREIGN KEY (tenant, artifact) REFERENCES artifact_revision (tenant, id),
  FOREIGN KEY (tenant, evaluation_definition) REFERENCES specification_pin (tenant, id),
  FOREIGN KEY (tenant, decision_case) REFERENCES decision_case (tenant, id),
  FOREIGN KEY (tenant, approved_option) REFERENCES decision_option (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE realization (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "pin" TEXT NOT NULL,
  "build_hash" TEXT NOT NULL,
  "manifest_digest" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, pin) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE repository (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "locator" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE specification_pin (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "repository" TEXT NOT NULL,
  "anchor" TEXT NOT NULL,
  "revision" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, repository) REFERENCES repository (tenant, id)
);

